// Install dependencies: yarn add @carbon/react@1.7.0 react react-dom

import React from 'react';
import ReactDOM from 'react-dom';
import { ProgressIndicator, ProgressStep } from '@carbon/react';
import '@carbon/react/css/carbon.min.css';

function App() {
  return (
    <div style={{ padding: '2rem', maxWidth: '320px' }}>
      <h3>Vertical Skeleton Progress Indicator</h3>
      <ProgressIndicator vertical skeleton>
        <ProgressStep />
        <ProgressStep />
        <ProgressStep />
        <ProgressStep />
      </ProgressIndicator>
    </div>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));
